class RecallAtK(BaseMetric):
    def __init__(self, k={{k}}, threshold={{threshold}}):
        self.k = k
        self.threshold = threshold
        self.evaluation_model = "recall-computer"
    def measure(self, test_case, *args, **kwargs):
        expected = set(test_case.expected_output.split(',')) if test_case.expected_output else set()
        retrieved = (test_case.retrieval_context or [])[:self.k]
        if not expected:
            self.score = 0
            self.success = False
            self.reason = '无 ground truth'
            return 0
        for codes in retrieved:
            if expected & set(codes):
                self.score = 1.0
                self.success = self.score >= self.threshold
                self.reason = f'前{self.k}位命中'
                return 1.0
        self.score = 0.0
        self.success = False
        self.reason = f'前{self.k}位未命中'
        return 0.0
    async def a_measure(self, test_case, *args, **kwargs):
        return self.measure(test_case)
    def is_successful(self):
        return bool(self.score is not None and self.score >= self.threshold)
    @property
    def __name__(self):
        return f'Recall@{self.k}'
